CREATE TABLE repair_sessions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),instructions TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('ready','generating','awaiting_review','awaiting_build','human_required','stopped','complete')),attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts<=2),reserved_tokens INTEGER NOT NULL DEFAULT 0 CHECK(reserved_tokens<=36096),created_at INTEGER NOT NULL,deadline_at INTEGER NOT NULL,proposal_id TEXT REFERENCES proposals(id),evidence_kind TEXT NOT NULL,evidence_id TEXT NOT NULL,revision INTEGER NOT NULL,evidence_digest TEXT NOT NULL,changed_paths TEXT NOT NULL DEFAULT '[]');
CREATE TABLE repair_events(id INTEGER PRIMARY KEY AUTOINCREMENT,session_id TEXT NOT NULL REFERENCES repair_sessions(id) ON DELETE CASCADE,kind TEXT NOT NULL,message TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX repair_one_active_user ON repair_sessions(user_id) WHERE status IN ('ready','generating','awaiting_review','awaiting_build');
CREATE TRIGGER repair_terminal_immutable BEFORE UPDATE OF status ON repair_sessions WHEN OLD.status IN ('stopped','complete','human_required') AND NEW.status<>OLD.status BEGIN SELECT RAISE(ABORT,'repair_terminal_immutable'); END;
CREATE TRIGGER repair_review_gate BEFORE UPDATE OF status ON repair_sessions WHEN NEW.status='awaiting_review' AND (OLD.status<>'generating' OR OLD.deadline_at<=CAST(strftime('%s','now') AS INTEGER)*1000 OR NOT EXISTS(SELECT 1 FROM projects WHERE id=OLD.project_id AND revision=OLD.revision)) BEGIN SELECT RAISE(ABORT,'repair_review_state_changed'); END;
CREATE TRIGGER repair_identity_immutable BEFORE UPDATE OF project_id,user_id,instructions,created_at,deadline_at ON repair_sessions BEGIN SELECT RAISE(ABORT,'repair_identity_immutable'); END;
